ALTER TABLE public.florist_requests ADD COLUMN delivery_address text, ADD COLUMN desired_delivery_time text, ADD COLUMN order_lines jsonb;
ALTER TABLE public.florist_requests ADD CONSTRAINT delivery_address_length CHECK (delivery_address IS NULL OR char_length(btrim(delivery_address)) BETWEEN 1 AND 500), ADD CONSTRAINT desired_delivery_time_length CHECK (desired_delivery_time IS NULL OR char_length(btrim(desired_delivery_time)) BETWEEN 1 AND 100), ADD CONSTRAINT delivery_details_complete CHECK ((delivery_address IS NULL AND desired_delivery_time IS NULL AND order_lines IS NULL) OR (delivery_address IS NOT NULL AND desired_delivery_time IS NOT NULL AND order_lines IS NOT NULL AND jsonb_typeof(order_lines) = 'array' AND jsonb_array_length(order_lines) BETWEEN 1 AND 100));
COMMENT ON COLUMN public.florist_requests.order_lines IS 'Unpaid delivery request snapshot from Shopify; not a duplicate catalog or paid order.';